/*
 * cfdrun_schema.js — V2 .cfdrun manifest structure definitions
 *
 * What V2 is: a frozen snapshot of one CFD run — STL artifacts, runtime inputs,
 * mesh/solver configuration, patch boundary bindings, source terms, and
 * postprocess config. Generated by the browser from live UI state at
 * export/mesh/solve time. Only schemaVersion=2 is accepted by the backend runner.
 *
 * BC_TYPES mirrors the bcType vocabulary implemented in fields.py / bridge_bc.py.
 * Do NOT add or rename entries here without a matching change in those files.
 *
 * Translators that READ live editor state and FILL a manifest live in
 * cfdrun_export.js (a separate module). This file is pure structure — no state
 * reading, no DOM access, no Three.js references.
 *
 * Dual-export: attaches to window.cfdrunSchema in the browser; exports via
 * module.exports for node --test (require() via createRequire in .mjs tests).
 */
(function () {
  'use strict';

  var CFDRUN_SCHEMA_VERSION = 2;

  /**
   * BC_TYPES — the set of bcType strings supported by the backend field generator.
   * Must stay in sync with fields.py and bridge_bc.py.
   */
  var BC_TYPES = new Set([
    'wall',
    'acu_supply',
    'acu_return',
    'fan_inlet',
    'fan_outlet',
    'nonfan_fixed_temp',
    'nonfan_heat_flux',
    'fixedTemperature',
    'heat_source_flux',
    'perforated_baffle',
    'wall_baffle',
    'through_zone',
  ]);

  /**
   * ROLES — patch-role vocabulary (domain semantics, not OpenFOAM patchField).
   * Derived from §"Patch 角色推导" in cfdrun-v2-schema.md.
   */
  var ROLES = new Set([
    'acu_supply',
    'acu_return',
    'fan_inlet',
    'fan_outlet',
    'chip_heat_source',
    'cold_plate_sink',
    'rdhx_surface',
    'perforated_baffle',
    'wall',
    'fixed_temperature',
    'heat_source_flux',
  ]);

  /**
   * emptyArtifacts() — returns a fresh RunArtifacts skeleton.
   * Backend fills these paths at write time; the browser exports an empty skeleton.
   */
  function emptyArtifacts() {
    return {
      caseDir: '',
      modelDir: '',
      triSurfaceDir: '',
      openfoamCaseDir: '',
      liquidResultsPath: null,
      logs: {},
    };
  }

  /**
   * emptyManifest() — returns a deep-fresh CfdrunV2 object with all 13 canonical
   * top-level keys. Every call builds all nested objects inline so there are no
   * shared nested references between calls.
   */
  function emptyManifest() {
    return {
      schemaVersion: CFDRUN_SCHEMA_VERSION,
      runId: '',
      name: '',
      sourceProject: null,
      inputs: {
        racks: {},
        acus: {},
        servers: {},
        cdus: {},
        partitionWalls: {},
        pipeSegments: {},
        liquid: { enabled: false, inheritResults: false },
        labels: { sensorMeasurements: {} },
      },
      geometryExport: {
        coordinateSystem: 'Y-up',
        unit: 'm',
        stlFiles: {},
        solids: {},
      },
      boundaryBindings: {},
      sourceTerms: {},
      porousBindings: {},
      meshConfig: {},
      simulationConfig: {},
      postprocessConfig: {
        probes: {},
        surfaceMonitors: {},
        outputFields: ['T', 'U', 'p_rgh'],
        labels: {},
      },
      artifacts: emptyArtifacts(),
    };
  }

  /**
   * validateManifest(json) — structural checker.
   * Returns string[] of error messages; empty array means structurally valid.
   * Checks:
   *   1. json.schemaVersion === 2
   *   2. All 13 required top-level keys present
   *   3. json.sourceProject (if non-null) has schemaVersion and contentHash
   *   4. boundaryBindings entries have bcType in BC_TYPES
   *   5. geometryExport.solids entries: role, if present, must be a string
   */
  function validatePressureLinearSolver(value, path, err) {
    if (value === undefined || value === null) return;
    if (typeof value !== 'object' || Array.isArray(value)) {
      err(path, 'must be an object or null'); return;
    }
    const keys = ['preconditioner', 'tolerance', 'relTol', 'maxIter'];
    for (const key of Object.keys(value)) {
      if (!keys.includes(key)) err(path + '.' + key, 'unknown pressure linear solver field');
    }
    for (const key of keys) {
      const field = value[key];
      if (field === undefined || field === null) continue;
      if (key === 'preconditioner') {
        if (field !== 'DIC' && field !== 'GAMG') err(path + '.' + key, 'must be DIC or GAMG');
      } else if (typeof field !== 'number' || !Number.isFinite(field) ||
        (key === 'tolerance' && field <= 0) ||
        (key === 'relTol' && (field < 0 || field >= 1)) ||
        (key === 'maxIter' && (!Number.isInteger(field) || field <= 0))) {
        err(path + '.' + key, 'invalid pressure linear solver numeric value');
      }
    }
  }

  function validateManifest(json) {
    var errors = [];

    if (!json || typeof json !== 'object') {
      errors.push('validateManifest: input is null or not an object');
      return errors;
    }

    // 1. schemaVersion — 3 is v2 plus a transient block and binding
    //    schedules (cfdrun v3, transient keyframes E7); 4 carries ONE
    //    simulationConfig, the root, and its transient block is optional (E8a).
    if (json.schemaVersion !== 2 && json.schemaVersion !== 3 && json.schemaVersion !== 4) {
      errors.push('schemaVersion must be 2, 3 or 4, got: ' + json.schemaVersion);
    }
    var tr = json.transient;
    if (json.schemaVersion === 3 || (json.schemaVersion === 4 && tr !== undefined)) {
      if (!tr || typeof tr !== 'object' || !(tr.durationS > 0) || !tr.start ||
          (tr.start.kind !== 'steadyConverged' && tr.start.kind !== 'uniform')) {
        errors.push('a transient manifest needs transient {durationS > 0, start.kind}');
      }
    } else if (tr !== undefined) {
      errors.push('a transient block needs schemaVersion 3 or 4');
    }
    if (json.schemaVersion === 4) {
      if (json.meshGeometry && json.meshGeometry.simulationConfig !== undefined) {
        errors.push('a schemaVersion 4 manifest carries one simulationConfig (the root); meshGeometry.simulationConfig must be absent');
      }
      if (!json.simulationConfig || typeof json.simulationConfig.roomTemperatureC !== 'number') {
        errors.push('a schemaVersion 4 manifest needs simulationConfig.roomTemperatureC');
      }
    }

    validatePressureLinearSolver(json.simulationConfig && json.simulationConfig.pressureLinearSolver, 'simulationConfig.pressureLinearSolver', (path, msg) => errors.push(path + ': ' + msg));

    // 2. Required top-level keys
    var REQUIRED_KEYS = [
      'schemaVersion', 'runId', 'name', 'sourceProject', 'inputs',
      'geometryExport', 'boundaryBindings', 'sourceTerms', 'porousBindings',
      'meshConfig', 'simulationConfig', 'postprocessConfig', 'artifacts',
    ];
    for (var i = 0; i < REQUIRED_KEYS.length; i++) {
      var k = REQUIRED_KEYS[i];
      if (!(k in json)) {
        errors.push('Missing required top-level key: ' + k);
      }
    }

    // 3. sourceProject — if non-null must have schemaVersion and contentHash
    if (json.sourceProject !== null && json.sourceProject !== undefined) {
      if (typeof json.sourceProject !== 'object') {
        errors.push('sourceProject must be an object or null');
      } else {
        if (!('schemaVersion' in json.sourceProject)) {
          errors.push('sourceProject is missing field: schemaVersion');
        }
        if (!('contentHash' in json.sourceProject)) {
          errors.push('sourceProject is missing field: contentHash');
        }
      }
    }

    // 4. boundaryBindings — each entry's bcType must be in BC_TYPES
    var bb = json.boundaryBindings;
    if (bb && typeof bb === 'object') {
      var bbKeys = Object.keys(bb);
      for (var j = 0; j < bbKeys.length; j++) {
        var bindingId = bbKeys[j];
        var binding = bb[bindingId];
        if (binding && typeof binding === 'object') {
          if ('bcType' in binding && !BC_TYPES.has(binding.bcType)) {
            errors.push(
              'boundaryBindings["' + bindingId + '"]: unknown bcType "' + binding.bcType + '"'
            );
          }
        }
      }
    }

    // 5. geometryExport.solids — role, if present, must be a string
    var ge = json.geometryExport;
    if (ge && typeof ge === 'object' && ge.solids && typeof ge.solids === 'object') {
      var solidKeys = Object.keys(ge.solids);
      for (var s = 0; s < solidKeys.length; s++) {
        var solidId = solidKeys[s];
        var solid = ge.solids[solidId];
        if (solid && typeof solid === 'object' && 'role' in solid) {
          if (typeof solid.role !== 'string') {
            errors.push(
              'geometryExport.solids["' + solidId + '"]: role must be a string, got ' + typeof solid.role
            );
          }
        }
      }
    }

    return errors;
  }

  // ---- dual export: browser window + Node.js module.exports ----
  if (typeof window !== 'undefined') {
    window.cfdrunSchema = {
      CFDRUN_SCHEMA_VERSION: CFDRUN_SCHEMA_VERSION,
      BC_TYPES: BC_TYPES,
      ROLES: ROLES,
      emptyArtifacts: emptyArtifacts,
      emptyManifest: emptyManifest,
      validateManifest: validateManifest,
    };
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      CFDRUN_SCHEMA_VERSION: CFDRUN_SCHEMA_VERSION,
      BC_TYPES: BC_TYPES,
      ROLES: ROLES,
      emptyArtifacts: emptyArtifacts,
      emptyManifest: emptyManifest,
      validateManifest: validateManifest,
    };
  }
})();
